package com.tianshu.assets.governance.infrastructure;
import com.tianshu.assets.governance.confirmation.application.AssetResponsibilityPort;import java.util.Optional;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository @Profile({"local","oceanbase"}) @ConditionalOnProperty(name="asset.governance-schema-enabled",havingValue="true")
public class JdbcAssetResponsibilityAdapter implements AssetResponsibilityPort {private final JdbcClient jdbc;public JdbcAssetResponsibilityAdapter(JdbcClient jdbc){this.jdbc=jdbc;}@Override public Optional<AssetResponsibility> currentResponsibility(long asset){return jdbc.sql("SELECT drawing_id,responsible_user_id,responsibility_scope FROM asset_responsibility_ext WHERE drawing_id=:id AND active=1 ORDER BY id DESC LIMIT 1").param("id",asset).query((r,n)->new AssetResponsibility(r.getLong("drawing_id"),r.getString("responsible_user_id"),r.getString("responsibility_scope"))).optional();}}
